def is_prime(n):
    if n <= 1: return False
    if n <= 3: return True
    if n % 2 == 0 or n % 3 == 0: return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def is_prime_power(num):
    if num <= 1:
        return None, 0

    # Find the smallest prime factor
    p = -1
    for i in range(2, int(num**0.5) + 1):
        if num % i == 0:
            p = i
            break
    if p == -1:
        # num is prime itself
        p = num

    # Check if num is a power of p
    if p == num:
        return p, 1 # This case violates a > 1 constraint, but we'll handle it later

    count = 0
    temp = num
    while temp > 1:
        if temp % p != 0:
            return None, 0 # Not a power of p
        temp //= p
        count += 1

    return p, count

# Function to check constraints: p must be prime, a > 1, b > 1
def check_triple(m, n, p):
    if not is_prime(p):
        return None

    try:
        # Check m^2 + n = p^a
        val1 = m**2 + n
        p1, a = is_prime_power(val1)
        if p1 != p or a < 2:
            return None

        # Check m + n^2 = p^b
        val2 = m + n**2
        p2, b = is_prime_power(val2)
        if p2 != p or b < 2:
            return None

        return (m, n, p)
    except OverflowError:
        # Safety check for very large numbers, though unlikely in m,n <= 10
        return None

